export const getUniqueClients = () => clients;

export const getUniqueEmpresas = (list: Client[] = clients) => {
  const seen = new Set<string>();
  return list.filter(c => {
    const key = c.empresa.toUpperCase().trim();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

export const getActiveClients = () => clients.filter(c => c.lojaSituacao.toLowerCase() === "ativo");
export const getCancelledClients = () => clients.filter(c => c.lojaSituacao.toLowerCase().includes("cancelado") || c.situacao === "CANCELADO");
export const getPausedClients = () => clients.filter(c => c.lojaSituacao.toLowerCase().includes("paus"));
export const getOverdueClients = () => clients.filter(c => ["ATRASO DO MÊS", "ATRASADO"].includes(c.situacao));

export const formatCurrency = (value: number) =>
  new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);

export const getStatusColor = (situacao: string): string => {
  switch (situacao) {
    case "PAGO": return "success";
    case "ATRASO DO MÊS":
    case "ATRASADO": return "warning";
    case "CANCELADO":
    case "SEM RESULTADO":
    case "EM CANCELAMENTO": return "destructive";
    case "PAUSADO": return "muted";
    case "A PAGAR":
    case "ACORDO": return "info";
    case "PENDÊNCIA": return "warning";
    case "NÃO COBRAR":
    case "SINAL":
    case "INATIVO": return "muted";
    default: return "secondary";
  }
};
